#!/bin/bash
# Intel CcP / Samsung 767XCL — candidato validado em 04/10/2026.
# Base: Linux 7.0.0 + RFC Cai Yu 25/09/2026 e correção de drvdata/velocidade.
# Instala o módulo DKMS e garante o firmware Intel Bluetooth no initramfs. Não modifica ISH, bateria, BIOS ou GRUB.
set -Eeuo pipefail
if (( EUID != 0 )); then exec sudo /bin/bash "$(readlink -f "$0")" "$@"; fi
name=galaxybook-lkf-bluetooth
version=0.1
source_dir=/usr/src/${name}-${version}
autoload=/etc/modules-load.d/galaxybook-lkf-bluetooth.conf
dracut_conf=/etc/dracut.conf.d/99-intel-bluetooth.conf
state_dir=/var/lib/galaxybook-linux-fixes/bluetooth
firmware_sfi=/usr/lib/firmware/intel/ibt-20-1-3.sfi
firmware_ddc=/usr/lib/firmware/intel/ibt-20-1-3.ddc
kernel=$(uname -r)
mode=${1:---instalar}
if [[ $mode == --remover ]]; then
    if [[ ! -d $source_dir && ! -f $autoload ]] && ! dkms status -m "$name" -v "$version" 2>/dev/null | grep -q .; then
        echo 'Este candidato não está instalado; nada a remover.'; exit 0
    fi
    modprobe -r hci_uart || { echo 'Bluetooth em uso; desligue os dispositivos e tente novamente.'; exit 1; }
    if dkms status -m "$name" -v "$version" | grep -q .; then dkms remove -m "$name" -v "$version" --all; fi
    rm -f "$autoload"
    rm -rf -- "$source_dir"
    if [[ -f "$state_dir/created-sfi" ]]; then rm -f "$firmware_sfi"; fi
    if [[ -f "$state_dir/created-ddc" ]]; then rm -f "$firmware_ddc"; fi
    rm -f "$dracut_conf"
    rm -rf -- "$state_dir"
    depmod -a
    if command -v dracut >/dev/null 2>&1; then dracut --force "/boot/initrd.img-$kernel" "$kernel" || true; fi
    echo 'Correção removida. O módulo original foi preservado. Reinicie quando conveniente.'
    exit 0
fi
[[ $mode == --instalar ]] || { echo 'Uso: bash este-script.sh [--instalar|--remover]'; exit 2; }
[[ $(cat /sys/class/dmi/id/product_name) == 767XCL ]] || { echo 'Este instalador é exclusivo do Samsung 767XCL.'; exit 1; }
[[ -d /sys/bus/acpi/devices/INT33E4:00 ]] || { echo 'Controlador Intel CcP INT33E4 ausente.'; exit 1; }
[[ $(cat /sys/bus/pci/devices/0000:00:1f.3/device) == 0x98c8 ]] || exit 1
[[ $kernel =~ ^7\.0\.0-[0-9]+-generic$ ]] || { echo "Kernel $kernel ainda não validado; nenhuma alteração feita."; exit 1; }
if command -v mokutil >/dev/null && mokutil --sb-state 2>/dev/null | grep -qi 'SecureBoot enabled'; then
    echo 'Secure Boot ativo: este candidato precisa de assinatura com chave autorizada. Nada será desativado.'; exit 1
fi
[[ ! -d /sys/module/hci_uart ]] || { echo 'hci_uart já carregado; reinicie antes de instalar este candidato.'; exit 1; }
if dkms status -m "$name" -v "$version" 2>/dev/null | grep -q .; then
    echo 'Este candidato já está registrado. Use --remover antes de reinstalar.'; exit 1
fi
[[ ! -e $source_dir && ! -e $autoload ]] || { echo 'Há arquivos anteriores nesses destinos; instalação interrompida para preservá-los.'; exit 1; }
stock_path=$(modinfo -n hci_uart)
[[ $stock_path != */updates/* && $stock_path != */extra/* ]] || { echo 'Outro módulo personalizado já instalado; preserve-o antes de prosseguir.'; exit 1; }
apt-get update
apt-get install -y --no-install-recommends build-essential dkms "linux-headers-$kernel" bluez linux-firmware linux-firmware-intel-wireless kmod dracut zstd xz-utils
install -d "$state_dir" /etc/dracut.conf.d
materialize_firmware() {
    local file=$1 marker=$2 resolved
    [[ -f "$file" ]] && return 0
    if [[ -f "$file.zst" ]]; then
        resolved=$(readlink -f "$file.zst")
        zstdcat "$resolved" > "$file"
        touch "$state_dir/$marker"
    elif [[ -f "$file.xz" ]]; then
        resolved=$(readlink -f "$file.xz")
        xzcat "$resolved" > "$file"
        touch "$state_dir/$marker"
    else
        echo "Firmware necessário ausente: $file"; exit 1
    fi
}
materialize_firmware "$firmware_sfi" created-sfi
materialize_firmware "$firmware_ddc" created-ddc
cat > "$dracut_conf" <<EOF
install_items+=" $firmware_sfi $firmware_ddc "
EOF
dracut --force "/boot/initrd.img-$kernel" "$kernel"
lsinitramfs "/boot/initrd.img-$kernel" | grep -q 'ibt-20-1-3.sfi' || { echo "Firmware SFI não entrou no initramfs."; exit 1; }
lsinitramfs "/boot/initrd.img-$kernel" | grep -q 'ibt-20-1-3.ddc' || { echo "Firmware DDC não entrou no initramfs."; exit 1; }
task_tmp=$(mktemp -d)
registered=0
committed=0
cleanup() {
    result=$?
    if (( ! committed )); then
        modprobe -r hci_uart 2>/dev/null || true
        (( ! registered )) || dkms remove -m "$name" -v "$version" --all || true
        rm -f "$autoload"
        rm -rf -- "$source_dir"
        rm -f "$dracut_conf"
        if [[ -f "$state_dir/created-sfi" ]]; then rm -f "$firmware_sfi"; fi
        if [[ -f "$state_dir/created-ddc" ]]; then rm -f "$firmware_ddc"; fi
        rm -rf -- "$state_dir"
        depmod -a || true
        if command -v dracut >/dev/null 2>&1; then dracut --force "/boot/initrd.img-$kernel" "$kernel" >/dev/null 2>&1 || true; fi
        echo 'Instalação não concluída; arquivos deste candidato foram revertidos.'
    fi
    rm -rf -- "$task_tmp"
    exit "$result"
}
trap cleanup EXIT
